#include <mutex>
#include <functional>

using namespace std;

class TrafficLight {
private:
    int greenRoad = 1;
    mutex mtx;

public:
    TrafficLight() {}

    void carArrived(
        int carId,
        int roadId,
        int direction,
        function<void()> changeGreen,
        function<void()> crossCar
    ) {
        lock_guard<mutex> lock(mtx);
        if (greenRoad != roadId) {
            greenRoad = roadId;
            changeGreen();
        }
        crossCar();
    }
};

class TrafficLight {
    private int greenRoad = 1;

    public TrafficLight() {}

    public synchronized void carArrived(
        int carId,
        int roadId,
        int direction,
        Runnable changeGreen,
        Runnable crossCar
    ) {
        if (greenRoad != roadId) {
            greenRoad = roadId;
            changeGreen.run();
        }
        crossCar.run();
    }
}
